  "up": "Select: compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism. Source: molecule_dictionary, molecule_hierarchy, compound_structures, compound_records, docs, activities, assays, target_dictionary. Join: molecule_dictionary parent ON parent.chembl_id = 'CHEMBL2105717'. Join molecule_hierarchy mh ON mh.parent_molregno = parent.molregno. Join molecule_dictionary child ON child.molregno = mh.molregno. Include parent row by joining molecule_hierarchy where parent.molregno = mh.parent_molregno OR parent.molregno = mh.molregno. Join compound_structures ON child.molregno = compound_structures.molregno. Join compound_records ON child.molregno = compound_records.molregno. Join docs ON compound_records.doc_id = docs.doc_id. Join activities ON compound_records.record_id = activities.record_id. Join assays ON activities.assay_id = assays.assay_id. Join target_dictionary ON activities.tid = target_dictionary.tid. Filter: target_dictionary.chembl_id = 'CHEMBL3717'. Filter: activities.standard_type = 'IC50'. Filter: activities.standard_units = 'nM'. Filter: activities.standard_value IS NOT NULL. Sort: compound_chembl_id ASC, compound_key ASC, pubmed_id_or_doi ASC, assay_description ASC, standard_type ASC, standard_relation ASC, standard_value ASC, standard_units ASC, target_chembl_id ASC, target_name ASC, target_organism ASC."
